"""The week of 7 Dec 2026's Tuesday and Thursday options (and, once written, Saturday's). Facts from ../research/
offdays.json and offdays2.json, each checked on its page by the research readers on 27 Nov 2026."""

LF_UTIL = "\"be really helpful to the layperson to understand what they can use when\" (your Improve, 16 Nov, of the assistants explainer)"
LF_INFO = "\"a more infographicy amusing explainer\" (your Improve, 9 Nov, of the phone-book tool-calls carousel)"
LF_FUN = "\"play on the hilarity of this topic\" (your Improve, 9 Nov, of the Home Depot homework option)"
LF_LAME = "\"The idea is lame. This doesn't translate into a carousel properly.\" (your Reject, 16 Nov): this one is built card by card"
TOOL = 'tool-unlock'
TOOL_BEATS = 'https://www.instagram.com/evolving.ai/p/DfZlAbRAISa/'
KIT = 'v5 Library explainer set: house type, brand palette, the vendor screenshot as the hero picture'


def carousel(id, hook, see, lands, why_now, share, src, copy, cards, steps, funny, take, learned, sector_story, fact, tie=None, rec=False):
    frames = [{'words': c[0], 'picture': c[1]} for c in cards]
    o = {'id': id, 'kind': 'explainer', 'format': f'Explainer carousel, {len(cards)} cards, 4:5', 'source': src, 'source_tag': 'trade_press',
         'copy': copy, 'hook': hook, 'story': sector_story, 'fact': fact,
         'pitch': {'see': see, 'lands': lands, 'why_now': why_now, 'share': share},
         'shape': 'story', 'dive': take, 'aim': 'utility', 'funny': funny,
         'lookalike': {'pattern': TOOL, 'beats': TOOL_BEATS, 'our_take': "The post listed what a coding tool unlocks; ours is the same card flow for one creative tool, with the real price and the catch."},
         'cards': [{'words': c[0], 'picture': c[1]} for c in cards], 'steps': steps,
         'learned_from': [learned],
         'direction': {'look': 'The v5 explainer look, modelled on the tool-unlock carousels in your Instagram inspo sheet', 'format': f'{len(cards)} cards, 4:5',
                       'frames': frames, 'tone': 'Plain, useful and a little dry: the joke is in the facts.', 'kit': KIT, 'inspo_url': TOOL_BEATS}}
    if tie:
        o['ties_to'] = tie
    if rec:
        o['recommended'] = True
    return o


def short(id, hook, see, lands, why_now, share, src, sources, copy, story, fact, funny, take, learned, pattern, beats, our_take, frames, aim):
    return {'id': id, 'kind': 'voiceover', 'format': 'Voiceover short, 9:16, about 60 seconds, motion graphics over the source pictures', 'source': src,
            'sources': sources, 'source_tag': 'trade_press', 'copy': copy, 'hook': hook, 'story': story, 'fact': fact,
            'pitch': {'see': see, 'lands': lands, 'why_now': why_now, 'share': share}, 'shape': 'story', 'dive': take, 'aim': aim, 'funny': funny,
            'lookalike': {'pattern': pattern, 'beats': beats, 'our_take': our_take}, 'learned_from': [learned],
            'direction': {'look': 'Voice-led motion graphics over the story\'s own pictures, art-directed captions', 'format': '9:16 short, about 60 seconds',
                          'frames': [{'words': f[0], 'picture': f[1]} for f in frames], 'tone': 'Deadpan: the facts carry the joke.', 'kit': 'v5 Library short: house type, brand palette, the designed captions', 'inspo_url': beats}}


